// CBET Fundamentals practice deck (v23). Original exam-style items mapped to the AAMI CBET outline. Data only.
LSA.deck({
  id: "cbet", name: "CBET Fundamentals", icon: "🔌",
  section: 'Engineer Fundamentals', format: 'practice',
  notice: "These are original practice questions written to official public outlines. They are not real past exam items, not an official NCEES or AAMI practice exam, and not a license to practice. Formulas were checked against standard public references. Consult the current FE Reference Handbook and applicable standards for official work.",
  sources: {
    "openstax-up2": ["OpenStax University Physics Volume 2", "https://openstax.org/books/university-physics-volume-2/pages/1-introduction"],
    "openstax-ap": ["OpenStax Anatomy and Physiology 2e", "https://openstax.org/books/anatomy-and-physiology-2e/pages/1-introduction"],
    "hhs-hipaa": ["HHS: HIPAA for Professionals", "https://www.hhs.gov/hipaa/for-professionals/index.html"],
    "nist-csf": ["NIST Cybersecurity Framework", "https://www.nist.gov/cyberframework"],
    "healthit": ["HealthIT.gov (ONC)", "https://www.healthit.gov/"],
    "osha-elec": ["OSHA Electrical Safety", "https://www.osha.gov/electrical"],
    "cdc-precautions": ["CDC: Standard Precautions for All Patient Care", "https://www.cdc.gov/infection-control/hcp/standard-precautions/index.html"],
    "cms-cops": ["CMS Conditions of Participation", "https://www.cms.gov/medicare/health-safety-standards/conditions-participation-requirements"],
    "fda-advice": ["FDA Device Advice: Comprehensive Regulatory Assistance", "https://www.fda.gov/medical-devices/device-advice-comprehensive-regulatory-assistance"],
    "fda-safety": ["FDA Medical Device Safety", "https://www.fda.gov/medical-devices/medical-device-safety"],
    "fda-infusion": ["FDA: Infusion Pumps", "https://www.fda.gov/medical-devices/general-hospital-devices-and-supplies/infusion-pumps"],
    "fda-defib": ["FDA: External Defibrillators and AEDs", "https://www.fda.gov/medical-devices/cardiovascular-devices/external-defibrillators-aeds-and-public-access-defibrillation"],
    "fda-pulseox": ["FDA: Pulse Oximeters", "https://www.fda.gov/medical-devices/general-hospital-devices-and-supplies/pulse-oximeters"],
    "fda-vent": ["FDA: Ventilators and Accessories", "https://www.fda.gov/medical-devices/products-and-medical-procedures/ventilators"],
    "fda-ultrasound": ["FDA: Ultrasound Imaging", "https://www.fda.gov/radiation-emitting-products/medical-imaging/ultrasound-imaging"],
    "fda-digital": ["FDA Digital Health Center of Excellence", "https://www.fda.gov/medical-devices/digital-health-center-excellence"],
    "nfpa-99": ["NFPA 99, Health Care Facilities Code (cited, not pasted)", "https://www.nfpa.org/codes-and-standards/nfpa-99-standard-for-health-care-facilities"],
    "iec-60601": ["IEC 60601-1 (FDA recognized consensus standard page; cited, not pasted)", "https://www.fda.gov/medical-devices/standards-and-conformity-assessment-program/recognized-consensus-standards-recognized-consensus-standards"],
    "aami-cbet": ["AAMI: Certified Biomedical Equipment Technician (CBET) exam content outline", "https://aami.org/certifications/cbet/"],
  },
  cards: [
    { id: "cb001", ages: 'both', topic: "anatomy", s: "The primary job of the heart is to:", c: ["Filter waste from the blood, as the kidneys do", "Pump blood through the circulatory system", "Exchange gases between air and blood, as alveoli do", "Store and concentrate bile, as the gallbladder does"], f: "The heart is a muscular pump that moves blood through the pulmonary and systemic circulations. Gas exchange occurs in the lungs, and the kidneys filter blood.", src: "openstax-ap" },
    { id: "cb002", ages: 'both', topic: "anatomy", s: "Gas exchange between air and blood occurs mainly in the:", c: ["The left ventricle", "Alveoli of the lungs", "The lining of the stomach wall", "The dry outer skin surface, a poor site for alveolar gas exchange"], f: "Gas exchange occurs in the alveoli of the lungs. Oxygen and carbon dioxide are exchanged across the alveolar-capillary membrane in the lungs. The left ventricle pumps oxygenated blood but does not perform that gas exchange.", src: "openstax-ap" },
    { id: "cb003", ages: 'both', topic: "anatomy", s: "The brain is part of which system?", c: ["The digestive system", "The nervous system", "The urinary system", "The integumentary system"], f: "The brain, spinal cord, and nerves make up the nervous system, which coordinates sensation, control, and many automatic functions.", src: "openstax-ap" },
    { id: "cb004", ages: 'both', topic: "anatomy", s: "Skin is the major organ of which system?", c: ["The respiratory tree", "The integumentary system", "The skeletal system", "The endocrine glands"], f: "Skin, hair, and associated glands form the integumentary system, a barrier that also helps with sensation and temperature control.", src: "openstax-ap" },
    { id: "cb005", ages: 'both', topic: "anatomy", s: "In medical terms, 'hypo-' as a prefix usually means:", c: ["Above or higher than normal", "Below or lower than normal", "Around or surrounding a structure", "Against or opposed to a structure"], f: "The prefix hypo- means below or lower than normal. Hypo- means under or below (as in hypotension, hypoglycemia). Hyper- means above or excessive. Peri- means around.", src: "openstax-ap" },
    { id: "cb006", ages: 'both', topic: "anatomy", s: "Blood returns to the right atrium of the heart mainly through the:", c: ["The aorta leaving the left ventricle", "Vena cava", "Pulmonary veins", "The bile duct of the biliary tree"], f: "Systemic venous blood enters the right atrium by the venae cavae. The aorta carries blood out of the left ventricle. Pulmonary veins return blood from the lungs to the left atrium.", src: "openstax-ap" },
    { id: "cb007", ages: 'both', topic: "anatomy", s: "The musculoskeletal system includes:", c: ["The lungs and airways of the respiratory system, the organs used in gas exchange", "Bones and joints, and muscles that support and move the body", "The liver and pancreas of the digestive system, the organs used in digestion", "The eyes and ears of the special senses, the organs used in hearing and vision"], f: "Bones, joints, cartilage, and muscles work together for support, protection, and movement. Lungs belong to the respiratory system.", src: "openstax-ap" },
    { id: "cb008", ages: 'both', topic: "electricity", s: "A 12 V source drives 0.010 A through a resistor. What is the resistance? Use Ohm's law \\(V=IR\\).", c: ["0.12 ohm", "1,200 ohm", "12 ohm", "120 ohm"], f: "Ohm's law rearranged is \\(R=V/I=12/0.010=1,200\\,\\Omega\\). Using \\(V I\\) or forgetting the decimal in the current are common mistakes.", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A simple series circuit with a voltage source and resistors." },
    { id: "cb009", ages: 'both', topic: "electricity", s: "Two resistors, \\(2.0\\,\\mathrm{k}\\Omega\\) and \\(2.0\\,\\mathrm{k}\\Omega\\), are in series with a 10 V source. What is the current?", c: ["5.0 mA", "2.5 mA", "10 mA", "2.5 A"], f: "Series resistance is \\(2.0+2.0=4.0\\,\\mathrm{k}\\Omega\\). Current is \\(I=V/R=10/4000=0.0025\\,\\mathrm{A}=2.5\\,\\mathrm{mA}\\).", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A series circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb010", ages: 'both', topic: "electricity", s: "Two \\(100\\,\\Omega\\) resistors are in parallel on a 10 V source. What is the total current from the source?", c: ["0.10 A", "0.20 A", "0.05 A", "20 A"], f: "Each branch draws \\(10/100=0.10\\,\\mathrm{A}\\), so the source current is \\(0.20\\,\\mathrm{A}\\). Equivalently \\(R_{\\mathrm{eq}}=50\\,\\Omega\\) and \\(I=10/50=0.20\\,\\mathrm{A}\\).", src: "openstax-up2", img: "img/cbet-parallel.svg", imgAlt: "A parallel circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb011", ages: 'both', topic: "electricity", s: "A device draws 2.0 A from a 24 V DC supply. What is the power?", c: ["12 W", "48 W", "26 W", "0.083 W"], f: "Electrical power is \\(P=VI=24(2.0)=48\\) W. Also \\(P=I^{2}R\\) or \\(V^{2}/R\\) once resistance is known.", src: "openstax-up2" },
    { id: "cb012", ages: 'both', topic: "electricity", s: "A line isolation monitor (LIM) in a healthcare isolated power system is used to:", c: ["Replace the need for equipment grounding in each building", "Warn of leakage or a first fault to ground on an isolated system", "Measure a patient's NIBP during a scheduled clinic visit", "Generate the ECG waveform from chest leads during a clinic visit"], f: "In isolated power systems used in some critical care areas, a LIM watches for a first ground fault or excessive leakage and alarms so the fault can be found before a second fault occurs.", src: "openstax-up2" },
    { id: "cb013", ages: 'both', topic: "electricity", s: "An uninterruptible power supply (UPS) is used mainly to:", c: ["Increase each wall outlet to 480 V throughout the clinic", "Bridge a short utility outage or transfer", "Sterilize instruments", "Replace batteries in implantable devices at the bedside"], f: "A UPS is used to bridge a short utility outage or transfer. A UPS provides short-term power (and often clean power) during a utility interruption until a generator starts or the load can be shut down safely. It is not a sterilizer.", src: "openstax-up2" },
    { id: "cb014", ages: 'both', topic: "healthit", s: "HIPAA rules for protected health information require that workforce members:", c: ["Post identifiable patient records on a public website to aid a research study after hours", "Use or share PHI as needed for treatment or payment or operations or another permitted purpose", "Store PHI on a personal phone for convenience, off the hospital record system in full", "Share a login password so a coworker can finish a late chart after hours, off the official record"], f: "HIPAA requires staff to use or share PHI only as needed for treatment, payment, operations, or another permitted purpose. The HIPAA Privacy Rule limits uses and disclosures of PHI and includes a minimum-necessary standard for many uses. Passwords must not be shared. Public posting of records is not permitted just for convenience.", src: "hhs-hipaa", also: ["nist-csf"] },
    { id: "cb015", ages: 'both', topic: "healthit", s: "A unique hardware address burned into a network interface is called a:", c: ["The subnet mask by itself", "MAC address", "The default gateway by itself", "The wireless SSID by itself"], f: "A MAC address identifies a network interface at the link layer. An IP address is a logical network-layer identifier and can change. A gateway is a router address; an SSID names a wireless network.", src: "healthit", also: ["nist-csf"] },
    { id: "cb016", ages: 'both', topic: "healthit", s: "IPv4 address 192.168.1.20 is commonly used as:", c: ["A public address that is unique worldwide on the routed Internet", "A private address that is not routable on the public Internet", "A hardware MAC address burned into a network interface card", "A default public DNS server address used on the open Internet"], f: "Addresses in 192.168.0.0/16 (and other RFC 1918 ranges) are private. They are not unique on the public Internet and are typically translated at a firewall.", src: "healthit", also: ["nist-csf"] },
    { id: "cb017", ages: 'both', topic: "healthit", s: "The PING utility is used mainly to:", c: ["Calibrate a defibrillator's delivered energy on a tester", "Test whether a host is reachable and measure round-trip time", "Install an operating-system update on a server in the closet", "Measure leakage current on a medical device with a safety analyzer"], f: "PING is used to test whether a host is reachable and measure round-trip time. PING sends ICMP echo requests and reports whether replies return. It is a basic network diagnostic, not a clinical calibration or OS-update tool.", src: "healthit", also: ["nist-csf"] },
    { id: "cb018", ages: 'both', topic: "healthit", s: "A medical device that cannot talk to the electronic medical record, even though the network is up, may have a problem with:", c: ["The wall outlet voltage in a distant building, a power quality issue", "The interface or middleware that maps device data to the EMR", "The steam supply feeding a sterilizer in CSSD", "The color of the monitor housing at the patient's bedside"], f: "Device-to-EMR integration often uses a gateway or middleware and a standard such as HL7. A mapping, license, or interface engine fault can block data even when the LAN is healthy.", src: "healthit", also: ["nist-csf"] },
    { id: "cb019", ages: 'both', topic: "healthit", s: "NIST cybersecurity guidance for systems that handle sensitive data emphasizes:", c: ["Antivirus on a single workstation, omitting another layer of control", "Govern and identify and protect and detect and respond and recover", "A single strong password policy for shared accounts", "Encrypting backups, omitting another administrative or technical control"], f: "NIST Cybersecurity Framework 2.0 organizes work into six functions: govern, identify, protect, detect, respond, and recover. Patching, access control, and monitoring support those functions.", src: "nist-csf" },
    { id: "cb020", ages: 'both', topic: "healthit", s: "A workstation will not boot and the display stays dark, even on a known-good monitor. A useful early hardware check is:", c: ["Reimaging the EMR server first, before a local check on a first look at a dark display", "Power supply rails and connections, and whether the board posts", "Replacing the hospital emergency generator first, before a local check", "Changing the patient's diet order in the chart, before a local check"], f: "On a dark workstation, first check power supply rails, connections, and whether the board posts. A dead workstation is often a local power, cable, memory, or motherboard problem. Confirm power and basic POST before blaming enterprise servers.", src: "healthit", also: ["nist-csf"] },
    { id: "cb021", ages: 'both', topic: "healthit", s: "Applying OS and application patches on networked medical systems is important because:", c: ["Patches are optional if the device still turns on and the display is lit", "Unpatched systems are a frequent path for malware and data breaches", "Updates should be delayed until a breach is already underway", "Clinical systems should be left unpatched after a tested process is available"], f: "Unpatched systems are a frequent path for malware and data breaches. Timely, tested patching reduces known vulnerabilities. Clinical systems still need a change process so a patch does not break a device or workflow.", src: "healthit", also: ["nist-csf"] },
    { id: "cb022", ages: 'both', topic: "healthit", s: "A wireless access point is used to:", c: ["Route packets between two different IP subnets, as a default gateway does", "Connect Wi-Fi clients to the wired network", "Step 120 V down to 5 V for logic boards", "Assign public IPv4 addresses to each wireless client"], f: "An access point is used to connect Wi-Fi clients to the wired network. An access point bridges wireless clients (and sometimes other APs) to the LAN. It is not a clinical instrument or a power transformer.", src: "healthit", also: ["nist-csf"] },
    { id: "cb023", ages: 'both', topic: "healthit", s: "A switch, as opposed to a simple hub, typically:", c: ["Broadcasts each frame to each port, by design of a modern switch", "Forwards frames toward the correct port based on MAC addresses", "Assigns HIPAA ID numbers", "Feeds isolated power from an isolation-transformer panel in the OR"], f: "A switch learns MAC addresses and forwards unicast frames out the needed port. A hub repeats to all ports. This reduces collisions and improves performance.", src: "healthit", also: ["nist-csf"] },
    { id: "cb024", ages: 'both', topic: "healthit", s: "A default gateway is:", c: ["The MAC address of a printer on the same desk on a public look-up service", "The router address a host uses to reach other networks", "The SSID of a guest Wi-Fi network", "A username used to log into the EMR on a workstation"], f: "A default gateway is the router address a host uses to reach other networks. If a destination is not on the local subnet, the host sends packets to its default gateway, which then routes them onward.", src: "healthit", also: ["nist-csf"] },
    { id: "cb025", ages: 'both', topic: "healthit", s: "Hardening a Windows PC used near a medical device should include:", c: ["One posted password that everyone in the unit shares", "Unique accounts and authentication, and timely updates", "An unlocked session that stays open on a shared workstation", "Administrator rights for each shared workstation login"], f: "A basic hardening set is unique accounts, authentication, and timely updates. Unique credentials, authentication, auto-lock, patching, and least privilege reduce the chance that one compromised session exposes PHI or device control. Shared posted passwords are a common audit finding.", src: "healthit", also: ["nist-csf"] },
    { id: "cb026", ages: 'both', topic: "healthit", s: "A virtual server is:", c: ["A physical server dedicated to one program, omitting a guest OS layer", "A guest operating system running on a hypervisor and sharing physical hardware", "A paper chart stored in a closet, off a server and omitting a hypervisor layer", "A stand-alone instrument that does not use a hypervisor or a guest operating system"], f: "A virtual machine is a guest operating system running on a hypervisor, sharing physical hardware. Virtualization lets multiple servers share one host. Medical device vendors may or may not support a virtualized server, so the support statement matters.", src: "healthit", also: ["nist-csf"] },
    { id: "cb027", ages: 'both', topic: "healthit", s: "Cloud computing for a clinic means, at a basic level:", c: ["A guarantee that HIPAA stops applying once the data leave the hospital building for a vendor", "Using computing resources delivered over a network frequently off site under a service model", "A requirement to keep each hospital server physically in the same exam room as the device", "A method for sterilizing surgical instruments inside a hospital data center rack"], f: "Cloud computing means using computing resources delivered over a network, frequently off site, under a service model. Cloud services provide on-demand computing or applications over a network. HIPAA still applies: a business associate agreement and security controls are needed when PHI is involved.", src: "healthit", also: ["nist-csf"] },
    { id: "cb028", ages: 'both', topic: "healthit", s: "A cable tester or toner is most useful when you need to:", c: ["Measure a patient's blood pressure during a clinical procedure", "Identify or verify a copper network run and its pairs", "Calibrate a pulse oximeter against a known SpO2 simulator", "Treat VF with a defibrillator on a patient in a code"], f: "A toner or cable tester is used to identify or verify a copper network run and its pairs. Testers and toners help prove a cable's identity, continuity, and sometimes pair mapping or length. They do not replace clinical calibration tools.", src: "healthit", also: ["nist-csf"] },
    { id: "cb029", ages: 'both', topic: "healthit", s: "HHS has published cybersecurity performance goals for healthcare because:", c: ["Healthcare organizations are rarely targeted and leave clinical systems untouched", "Attacks on hospitals and clinics disrupt care and expose PHI", "Ransomware is treated as a retail-store problem, leaving hospitals aside", "PHI on a hospital network does not need special protection"], f: "Attacks on hospitals and clinics can disrupt care and expose PHI. Healthcare is a frequent ransomware and breach target. Federal performance goals and HIPAA security requirements aim to keep systems and PHI safer so care can continue.", src: "healthit", also: ["nist-csf"] },
    { id: "cb030", ages: 'both', topic: "healthit", s: "A KVM switch is used to:", c: ["Analyze blood samples in the clinical laboratory", "Share a keyboard and video, and a mouse among computers", "An isolation transformer for surgical-suite outlets", "Measure oxygen concentration in a medical-gas blender"], f: "A KVM switch is used to share a keyboard, video, and mouse among computers. KVM hardware (or software) lets one set of human-interface devices control multiple computers. It is not a lab analyzer or an isolated-power device.", src: "healthit", also: ["nist-csf"] },
    { id: "cb031", ages: 'both', topic: "function", s: "Korotkoff sounds are used when measuring:", c: ["Core body temperature with a probe or tympanic thermometer during a routine set", "Blood pressure with a cuff and stethoscope, or a simulator of that method", "End-tidal carbon dioxide on a capnograph during a case", "Electrical safety leakage on a medical device safety analyzer"], f: "Korotkoff sounds are the noises heard over an artery as a cuff deflates, used in auscultatory blood-pressure measurement. Automatic NIBP devices often use oscillometry instead, but the underlying clinical quantity is still blood pressure.", src: "fda-advice" },
    { id: "cb032", ages: 'both', topic: "function", s: "Einthoven's triangle refers to:", c: ["A method for leveling a surgical table used to set table tilt", "The three standard limb leads of the ECG", "A radiation warning sign posted on a door", "A battery chemistry used in a pack"], f: "Einthoven's triangle is formed by the three standard limb leads of the ECG. Einthoven's triangle is formed by leads I, II, and III on the right arm, left arm, and left leg. It is a basic ECG lead model, not a table or safety-sign topic.", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform showing P, QRS, and T waves." },
    { id: "cb033", ages: 'both', topic: "function", s: "On a normal ECG, the QRS complex mainly represents:", c: ["Atrial depolarization (the P wave)", "Ventricular depolarization", "Ventricular repolarization (the T wave)", "A blood-pressure Korotkoff sound"], f: "The P wave is atrial depolarization, the QRS is ventricular depolarization, and the T wave is ventricular repolarization. Technicians should recognize a normal pattern without diagnosing a patient.", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG waveform with the P wave, QRS complex, and T wave labeled.", imgAsk: true },
    { id: "cb034", ages: 'both', topic: "function", s: "A defibrillator analyzer is used to:", c: ["Treat a patient in cardiac arrest in a code, as a therapy device would", "Measure a defibrillator's output energy in a test setting", "Record a diagnostic 12-lead ECG on a patient in a clinic exam room", "Pace a chronic low heart rate as a permanent implant"], f: "A defibrillator analyzer is test equipment. It lets a technician verify delivered energy and other functions on a schedule, not treat a patient.", src: "fda-defib" },
    { id: "cb035", ages: 'both', topic: "function", s: "An electrical safety analyzer is used to:", c: ["Monitor a patient's bedside ECG waveform during a clinical procedure", "Measure leakage current and ground resistance, and similar safety points", "Apply defibrillator energy to a patient during a resuscitation code", "Sterilize surgical instruments in a timed steam sterilization cycle"], f: "A safety analyzer is used to measure leakage current, ground resistance, and similar safety points. Safety analyzers check protective earth, insulation, and leakage against the limits in the applicable standard (for example IEC 60601 or a facility policy based on NFPA 99). They are not clinical monitors.", src: "fda-safety" },
    { id: "cb036", ages: 'both', topic: "function", s: "A physiologic simulator is used to:", c: ["Treat a patient who has a dangerous rhythm, instead of using a defibrillator", "Provide known test signals such as ECG or pressure or SpO2 to a monitor", "Warm IV fluids for infusion in the operating room as a fluid warmer would", "Generate the hospital's EMR backup on a file server"], f: "A physiologic simulator is used to provide known test signals, such as ECG, pressure, or SpO2, to a monitor. Simulators let you test a monitor or module with a known waveform or value so you can tell a device fault from a cable or electrode problem.", src: "fda-advice" },
    { id: "cb037", ages: 'both', topic: "function", s: "Blood pressure in the clinic is commonly reported in:", c: ["Lumens, a lighting output unit used for lamps", "Millimeters of mercury (mmHg)", "Becquerel, a radioactivity unit used in nuclear medicine", "Siemens, a conductance unit used in electronics"], f: "Blood pressure is reported in millimeters of mercury (mmHg). Arterial blood pressure is measured in mmHg. Lumens measure light, becquerel is activity, and siemens is conductance.", src: "fda-advice" },
    { id: "cb038", ages: 'both', topic: "function", s: "A pulse oximeter estimates:", c: ["End-tidal carbon dioxide measured from exhaled gas on a breathing circuit", "Arterial oxygen saturation from light absorbed by a pulsatile vascular bed", "Core body temperature estimated from a skin-surface probe", "Invasive arterial pressure obtained from a pressurized flush bag"], f: "SpO2 is arterial oxygen saturation from light absorbed by a pulsatile vascular bed. Pulse oximetry uses at least two light wavelengths and a pulsatile signal to estimate SpO2. EtCO2 is a capnography measurement, not the same sensor.", src: "fda-pulseox" },
    { id: "cb039", ages: 'both', topic: "function", s: "End-tidal CO2 (EtCO2) monitoring is used mainly to:", c: ["Take the place of pulse-oximeter readings on each monitored case in the unit", "Follow carbon dioxide in exhaled gas frequently during sedation or ventilation", "Measure core temperature with a bladder or esophageal probe during a case", "Deliver a controlled electrical shock during defibrillation of a patient in a code"], f: "Capnography is used to follow carbon dioxide in exhaled gas, frequently during sedation or ventilation. Capnography reports CO2 in exhaled gas and is a key check of ventilation and airway integrity. It complements, rather than always replaces, oximetry.", src: "fda-advice" },
    { id: "cb040", ages: 'both', topic: "function", s: "A telemetry system in a hospital is used to:", c: ["Sterilize instruments in a central sterile processing department", "Send physiologic waveforms from a mobile patient to a central station", "An isolation panel that limits fault current in a wet procedure room in the OR", "Blend medical gases at a wall outlet in a patient room"], f: "Telemetry is used to send physiologic waveforms from a mobile patient to a central station. Telemetry uses radios or a network to carry ECG and related signals so a patient can move while being watched at a central station.", src: "fda-digital" },
    { id: "cb041", ages: 'both', topic: "function", s: "An infusion pump (LVP or syringe) is designed to:", c: ["Deliver a defibrillation shock with the infusion pump", "Deliver fluids or medications at a controlled rate", "Measure body temperature", "Provide mechanical ventilation of the lungs for a patient"], f: "Infusion devices control rate and volume. Different types (large-volume, syringe, PCA, and injectors) fit different therapies, but the core function is controlled delivery.", src: "fda-infusion" },
    { id: "cb042", ages: 'both', topic: "function", s: "A PCA pump is intended to:", c: ["Ventilate a patient who cannot breathe, as a substitute for a ventilator", "Let a patient request extra pain doses within programmed limits", "Record a 12-lead ECG for a diagnostic cardiology study", "Warm a whole operating table for patient comfort during a case"], f: "A PCA pump can let a patient request extra pain doses within programmed limits. Patient-controlled analgesia pumps give a programmed basal and/or demand dose with lockout limits. They are not ventilators or ECG machines.", src: "fda-infusion" },
    { id: "cb043", ages: 'both', topic: "function", s: "A ventilator is life-support equipment whose basic job is to:", c: ["Measure arterial pressure with an arm cuff on a spontaneously breathing patient", "Support or replace a patient's breathing", "Record an ECG from chest leads at the bedside", "Warm blankets in a cabinet before surgery"], f: "A ventilator is used to support or replace a patient's breathing. Ventilators deliver a controlled gas pattern to support ventilation. They require trained use, alarms, and backup power. They are not simple monitors.", src: "fda-vent" },
    { id: "cb044", ages: 'both', topic: "function", s: "An external defibrillator is used to:", c: ["Pace a chronic low heart rate as a permanently implanted pacemaker", "Deliver a controlled shock for certain dangerous heart rhythms", "Measure oxygen saturation with a pulse-oximeter probe", "Replace a wall suction regulator on the headwall outlet"], f: "A defibrillator is used to deliver a controlled shock for certain dangerous heart rhythms. Defibrillators treat shockable arrhythmias under clinical protocols. An implanted pacemaker is a different device. External transcutaneous pacing is a related but separate function on some units.", src: "fda-defib" },
    { id: "cb045", ages: 'both', topic: "function", s: "An electrosurgical unit (ESU) is used in the operating room to:", c: ["Ventilate the patient as its designed job", "Cut or coagulate tissue with a high-frequency current", "Record fetal heart rate during labor", "Sterilize the whole operating room by filling it with steam"], f: "An electrosurgical unit is used to cut or coagulate tissue with a high-frequency current. ESUs deliver RF current through an active electrode, with a return path (monopolar) or between the tips (bipolar). Safe use depends on return-electrode integrity, accessories, and smoke control.", src: "fda-advice" },
    { id: "cb046", ages: 'both', topic: "safety", s: "Patient leakage current, as used in electrical safety testing of medical equipment, is:", c: ["Current in the protective earth conductor during a fault condition", "Current that flows in an applied part connected to the patient", "The same measurement as earth leakage in either safety-analyzer test setup", "The current the device draws from the wall outlet under load"], f: "Patient leakage is current in the applied-part path that can reach the patient. Earth leakage is current in the protective-earth conductor. IEC 60601-1 and NFPA 99 treat these as different tests with different limits. Use the method and limits in the edition that applies to that device, and do not paste or memorize unofficial tables in place of the standard.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb047", ages: 'both', topic: "function", s: "A steam sterilizer (autoclave) uses which combination as its basic killing method?", c: ["Dry room air at 20 C circulated over the load for a timed interval", "Saturated steam under pressure for a defined time and temperature", "A UV night-light mounted over a bench as a substitute cycle", "A paper wrap around the load, omitting heat and steam from the cycle"], f: "Steam sterilization uses saturated steam under pressure for a defined time and temperature. Steam sterilizers use moist heat at a controlled temperature and time (and often a documented load process). Dry, cool air or a night-light is not a sterilization cycle.", src: "fda-advice" },
    { id: "cb048", ages: 'both', topic: "function", s: "A laboratory centrifuge is used to:", c: ["Ventilate a patient in an ICU bay as a life-support ventilator would", "Separate components of a sample by spinning it", "Deliver an IV medication bolus with a handheld syringe", "Image a joint with diagnostic X-rays in the radiology department"], f: "Centrifuges spin samples so denser components move outward. Imbalance, lid interlocks, and speed verification are typical safety and performance points.", src: "fda-advice" },
    { id: "cb049", ages: 'both', topic: "function", s: "A laboratory refrigerator or freezer is important because:", c: ["It stands in for a defibrillator during an emergency on the unit", "It keeps reagents and samples in a controlled temperature range", "It sterilizes steel tools by freezing them in the cabinet", "It supplies isolated power for surgical-suite outlets in the OR"], f: "A lab refrigerator or freezer keeps reagents and samples in a controlled temperature range. Lab cold storage must hold a set range, often with alarms and monitoring. Freezing is not a sterilizer for surgical tools, and it is not a power system.", src: "fda-advice" },
    { id: "cb050", ages: 'both', topic: "function", s: "An ultrasound imager forms pictures mainly by:", c: ["Using a strong static magnetic field and radiofrequency pulses, as in MRI", "Sending high-frequency sound and receiving echoes", "Detecting emitted gamma rays, as in a nuclear-medicine camera", "Imaging skin temperature with a thermal camera"], f: "Diagnostic ultrasound works by sending high-frequency sound and receiving echoes. Diagnostic ultrasound transmits pulses and listens for reflections. MRI uses magnetic fields and radiofrequency; nuclear medicine uses radioactive tracers.", src: "fda-ultrasound" },
    { id: "cb051", ages: 'both', topic: "function", s: "A digital multimeter (DVM) in a shop is used to:", c: ["Measure a patient's core temperature in the recovery bay after a case", "Measure voltage or current, or resistance in a circuit under test", "Deliver pacing pulses to a heart from an external pacemaker pack", "Print patient wristbands at a hospital admissions desk"], f: "A DVM is used to measure voltage, current, or resistance in a circuit under test. A DVM is general test equipment. Use it on de-energized circuits where required, with the right function and range, and never as a substitute for a medical-grade safety analyzer when that test is needed.", src: "fda-advice" },
    { id: "cb052", ages: 'both', topic: "function", s: "An SCD (sequential compression device) is used to:", c: ["Defibrillate the heart during a resuscitation code, treating the sleeves as a defibrillator", "Inflate garments on a limb in a cycle to help reduce stasis", "Provide mechanical ventilation for an ICU patient who cannot breathe", "Measure end-tidal CO2 on a breathing circuit as a capnograph would"], f: "SCDs inflate garments on a limb in a cycle to help reduce stasis. SCDs apply intermittent pneumatic compression, often to the legs, as a preventive therapy. They are not life-support ventilators or defibrillators.", src: "fda-advice" },
    { id: "cb053", ages: 'both', topic: "function", s: "A patient warmer or thermal blanket system is used to:", c: ["Record a diagnostic ECG waveform in clinic", "Help manage a patient's body temperature", "Measure urine volume collected in a drainage bag", "Provide continuous wall suction for airway clearance"], f: "Temperature-management devices heat or, in some systems, also cool a patient under a protocol. Over- or under-heating is a risk, so probes, alarms, and accessories matter.", src: "fda-advice" },
    { id: "cb054", ages: 'both', topic: "function", s: "A wall suction regulator is used to:", c: ["Raise oxygen concentration in a blender as a medical-gas blender would", "Control vacuum applied to a suction circuit", "Pace the heart with an external pulse generator", "Measure NIBP at the bedside with an arm cuff"], f: "A suction regulator is used to control vacuum applied to a suction circuit. Suction regulators set and limit vacuum from a wall or portable source. They are not oxygen blenders or pacing devices.", src: "fda-advice" },
    { id: "cb055", ages: 'both', topic: "function", s: "A fetal monitor typically tracks:", c: ["An adult 12-lead ECG as its designed purpose on an adult patient in clinic", "Fetal heart rate and uterine activity, such as a TOCO or IUP signal", "Laboratory centrifuge speed in the core laboratory", "Chamber pressure on a steam sterilizer in SPD"], f: "A fetal monitor records fetal heart rate and uterine activity, such as a TOCO or IUP signal. Fetal monitors record FHR and contractions (TOCO on the abdomen, or intrauterine pressure when indicated) so clinicians can assess well-being in labor or testing.", src: "fda-advice" },
    { id: "cb056", ages: 'both', topic: "function", s: "An anesthesia machine, at a basic level, is used to:", c: ["Wash and sterilize surgical instruments after an operating-room case", "Deliver a controlled mix of gases and anesthetic and support ventilation", "Store medical records and anesthetic charts for the anesthesia service", "Measure a newborn's weight on a scale in the nursery after delivery"], f: "An anesthesia workstation is used to deliver a controlled mix of gases and anesthetic and support ventilation. Anesthesia workstations blend gases, vaporize agent, and ventilate, with many safety interlocks and scavengers. They are life-support systems and are not sterilizers.", src: "fda-advice" },
    { id: "cb057", ages: 'both', topic: "function", s: "An external pacemaker (for example a transcutaneous or temporary external unit) is used to:", c: ["Measure SpO2 with a finger probe at the bedside as a pulse oximeter would", "Deliver temporary external pacing pulses when that strategy is indicated", "Warm IV fluids in the operating room as a fluid warmer would", "Replace a steam sterilizer used in SPD"], f: "External or temporary pacemakers provide pacing pulses under a clinical protocol. They are not oximeters or sterilizers. Implantable pacemakers are a different class of device.", src: "fda-advice" },
    { id: "cb058", ages: 'both', topic: "function", s: "A fluid warmer is used in perioperative or emergency care to:", c: ["Defibrillate a patient during a code, rather than calling for a defibrillator", "Warm fluids or blood products before they are infused", "Record EEG waveforms in a neurology laboratory", "Replace a UPS at a nursing-station workstation"], f: "A fluid warmer is used to warm fluids or blood products before they are infused. Fluid warmers reduce the chance of hypothermia from cold infusions. They must be used with the right disposables and temperature limits. They are not defibrillators.", src: "fda-advice" },
    { id: "cb059", ages: 'both', topic: "function", s: "A spirometer is a diagnostic device used to:", c: ["Shock the heart during defibrillation, skipping a paddles check", "Measure how much and how fast a person moves air", "Dialyze blood in a renal treatment area during a session", "Measure blood glucose at the bedside with a meter"], f: "Spirometry is used to measure how much and how fast a person can move air. Spirometry records volumes and flow for pulmonary testing. Calibration with a syringe and infection-control practices are typical technical points.", src: "fda-advice" },
    { id: "cb060", ages: 'both', topic: "function", s: "An otoscope is used to:", c: ["Look at the retina as its main designed use", "Look into the ear canal", "Measure blood pressure", "Ventilate the lungs"], f: "An otoscope illuminates and magnifies the ear canal and eardrum. An ophthalmoscope is the related tool for the eye.", src: "fda-advice" },
    { id: "cb061", ages: 'both', topic: "troubleshooting", s: "A monitor is completely dark, and no power light is on. The wall outlet is live. A sound first check is:", c: ["The SpO2 probe and cable as the first power check before an inlet or cord check", "The power cord and switch, and the inlet fuse or breaker and then the supply", "A steam sterilizer calibration used as the first power check", "The EMR vendor called as the first power check"], f: "No lights often means no power reaching the device. Check the obvious path (cord, switch, fuse or breaker, then the supply) before swapping major boards or blaming the network.", src: "fda-digital" },
    { id: "cb062", ages: 'both', topic: "troubleshooting", s: "A physiologic monitor shows a flat ECG and a 'leads off' message, but a simulator on the same cable is normal. The more likely problem is:", c: ["A failed display backlight, because the trace would still be stored", "The electrodes or skin prep or lead wires on the patient", "The hospital emergency generator in the plant", "The steam supply to a sterilizer elsewhere"], f: "If a known-good simulator works, the input and cable path are probably fine. The next place to look is the connection to the patient: electrodes, prep, and lead wires.", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform used as a known test pattern." },
    { id: "cb063", ages: 'both', topic: "troubleshooting", s: "Two work orders arrive: a ventilator in use on a patient has a critical alarm, and a scale in a clinic is slightly out of date for its check. Which should you handle first?", c: ["The scale, because it is easier to finish a low-risk job first", "The in-use ventilator, because of risk and urgency", "Neither job, until the next business day begins", "The scale, because it is the older of the two devices"], f: "Prioritize by risk, urgency, and effect on care. Life-support equipment in use comes before a noncritical clinic scale.", src: "fda-vent" },
    { id: "cb064", ages: 'both', topic: "troubleshooting", s: "A nurse reports 'the infusion pump is broken' after a dose was entered incorrectly and the pump alarmed as designed. This is best classified as:", c: ["A complete device failure, omitting a further check of how the pump was used", "A use-related issue, after you confirm the pump behaves as designed", "A steam-sterilizer fault found in CSSD", "A utility power outage on that hospital floor"], f: "If the pump is working as designed, treat the event as a use-related issue, after you confirm the pump behaves as designed. If the device alarms and behaves as designed when a wrong entry is made, the event may be a use error. Still verify the pump, then help with training or a workflow change. Do not skip the technical check.", src: "fda-infusion" },
    { id: "cb065", ages: 'both', topic: "troubleshooting", s: "One telemetry transmitter on a hall drops out, but the whole unit's other transmitters are fine. You should first suspect:", c: ["A campus-wide network collapse, before a check of that transmitter", "That transmitter or its battery or its antenna or a local dead zone", "A failure of each central station in the hospital at once", "A failed nurse-call dome light on another hospital floor"], f: "A single-device problem is more often local (battery, antenna, that radio, or a dead spot) than a system-wide failure. Compare with nearby working devices.", src: "fda-digital" },
    { id: "cb066", ages: 'both', topic: "troubleshooting", s: "Every telemetry display on a unit fails at once, while other hospital networks still work. That pattern suggests:", c: ["A single patient's electrode pack, after several telemetry beds failed at once on the unit", "A shared-system problem such as an access point or controller or that unit's path", "A single bed scale in one room, too local to take down the whole telemetry unit", "A single cracked otoscope bulb, affecting one exam tool on that floor"], f: "When many units fail together, look for a shared-system problem, such as an access point, controller, or that unit's path. When many devices of one system fail together, look at shared infrastructure, not one accessory. Isolate whether the fault is wireless, a switch, a server, or a central station.", src: "fda-digital" },
    { id: "cb067", ages: 'both', topic: "troubleshooting", s: "A newly installed monitor will not send data to the EMR, but waveforms look correct at the bedside. A useful early step is:", c: ["Replace the patient's IV catheter as a first technical step for a charting fault", "Confirm network settings and device ID, and the interface or middleware status", "Increase the defibrillator energy as a first step for a documentation fault", "Disable interface logging so the gap in the record stays hidden"], f: "If the bedside display is fine but the record is empty, confirm network settings, device ID, and the interface or middleware status. Bedside operation can be fine while ADT or results never reach the record because of IP, ports, time, a certificate, or a mapping in middleware. Check those before swapping a working display.", src: "fda-digital" },
    { id: "cb068", ages: 'both', topic: "troubleshooting", s: "A staff member needs a short in-service on a new vital-signs monitor. Your communication should be:", c: ["A guess about off-label workarounds you have not checked before you have verified the wording", "Clear in plain language and limited to safe approved use", "Advice that patient names can be posted on a public status board", "A request that they ignore the alarms"], f: "Technicians often train clinicians on proper use. Stay inside approved functions, be clear, and do not invent workarounds that bypass safety.", src: "fda-advice" },
    { id: "cb069", ages: 'both', topic: "troubleshooting", s: "A defibrillator fails an energy-output test on a defibrillator analyzer, but the device powers on. The right next path is:", c: ["Return it to the crash cart for the next code after a failed energy test", "Remove it from service and investigate and repair or escalate per policy", "Postpone the investigation until the next scheduled preventive-maintenance visit", "Leave the failed reading in the file and keep the unit in service"], f: "Remove it from service, investigate, and repair or escalate per policy. A failed energy test means the device must not stay in clinical service. Tag it, document, and follow the service procedure. Do not use people as test loads.", src: "fda-defib" },
    { id: "cb070", ages: 'both', topic: "troubleshooting", s: "An ESU repeatedly faults with a return-electrode alarm. A practical first check is:", c: ["The active electrode tip and a worn footswitch first, before the return path", "The return pad and its cable and how it is applied then the generator return circuit", "The isolated-power panel in a nearby procedure room first, before the return path", "The dispersive pad alarm set-point on a different generator first, before this unit's pad"], f: "Return-electrode (REM or CQM) alarms are often an accessory or application issue. Confirm the pad and cable before condemning the generator, then test the unit if the accessories are good.", src: "fda-advice" },
    { id: "cb071", ages: 'both', topic: "troubleshooting", s: "A syringe pump stops and reports occlusion. A sound first set of checks is:", c: ["The wall suction regulator on the same bed, a different fluid path than the infusion pump", "The tubing and clamps and position and whether the alarm is real then the pump", "The fire-alarm panel for that floor, a building system rather than the infusion line", "The nurse-call handset at the same bed, a communications device rather than the pump"], f: "Occlusion alarms are often clamps, kinks, a closed stopcock, or a high back-pressure site. Rule those out, then test the pump's pressure sensing if the fluid path is clear.", src: "fda-infusion" },
    { id: "cb072", ages: 'both', topic: "troubleshooting", s: "A PCA pump can be started, but the lockout interval does not match the order. After confirming the order, you should:", c: ["Tell the patient to ignore the lockout interval and keep using the pump for demand doses", "Treat it as a programming or configuration problem and keep the pump unused until it is correct", "Raise the lockout limit yourself, past the ordered dose, and leave the pump in clinical use", "Leave it in clinical service because the motor still runs and the screen is still lit"], f: "Treat it as a programming or configuration problem and keep the pump unused until it is correct. A lockout that does not match the prescribed program is a safety issue. Do not leave it in service or change therapy limits without the proper clinical and technical process.", src: "fda-infusion" },
    { id: "cb073", ages: 'both', topic: "troubleshooting", s: "A feeding pump free-flows when the door is open and no set is loaded correctly. That is:", c: ["Normal for this class of pump, so leave it in use after a free-flow finding", "A serious safety fault; take the pump out of service", "A cosmetics issue on the pump housing", "A reason to add more free-flow during a shop test"], f: "Free-flow is a serious safety fault; take the pump out of service. Free-flow of enteral or IV fluid when the set is not properly engaged is a serious hazard. The device should be removed from service and repaired or replaced.", src: "fda-advice" },
    { id: "cb074", ages: 'both', topic: "troubleshooting", s: "A laboratory centrifuge will not start, and the lid interlock light stays open even when the lid is closed. A likely cause is:", c: ["A worn drive motor, while the lid switch still reads closed", "A lid switch or latch or interlock fault", "A speed-program typo that still shows a closed lid", "A failed brake that would still allow a start with a closed lid"], f: "Centrifuges should not run with the lid open. If the interlock never sees 'closed,' look at the switch, latch, and wiring before replacing a motor.", src: "fda-advice" },
    { id: "cb075", ages: 'both', topic: "troubleshooting", s: "A lab refrigerator used for reagents is at 12 C, above its set range, and the alarm did not call. You should:", c: ["Leave the reagents and samples in place until the next scheduled temperature check next week", "Protect the contents and take the box out of use as needed and find why cooling and the alarm both failed", "Turn the failed box into a backup room warmer for the laboratory workspace and keep the stock inside", "Disable the remaining temperature alarms so the display looks normal to staff on that bench"], f: "Protect the contents, take the box out of use as needed, and find why cooling and the alarm both failed. Out-of-range storage can ruin reagents or samples. Safeguard the contents, then repair the refrigeration and the alarm path. Do not silence alarms to hide the problem.", src: "fda-advice" },
    { id: "cb076", ages: 'both', topic: "troubleshooting", s: "An otoscope light is dim. The handle has fresh batteries. A simple next check is:", c: ["The hospital MRI zoning signs at the entrance", "The lamp and contacts, and the head connection", "The steam generator pressure in central sterile", "The EMR database index on the application server"], f: "A dim otoscope is often a lamp, dirty contacts, or a poor connection in the head or handle. Power is already plausible if the batteries are good.", src: "fda-advice" },
    { id: "cb077", ages: 'both', topic: "troubleshooting", s: "A scale used for medication dosing reads 0.4 kg high on a known test weight. You should:", c: ["Leave it in service and tell staff to subtract 0.4 kg in their heads and keep using it for dosing", "Remove it from clinical dosing use until it is calibrated or replaced", "Ignore the 0.4 kg error and keep the scale in dosing use", "Use it to weigh gas cylinders, with the same error, and still use it for drugs"], f: "Remove it from clinical dosing use until it is calibrated or replaced. A scale used for dosing must be accurate. Take it out of that use, calibrate or repair it, and document. Mental corrections are not a safe standing practice.", src: "fda-advice" },
    { id: "cb078", ages: 'both', topic: "troubleshooting", s: "A stress-test ECG is noisy only when the treadmill is running. A useful direction is:", c: ["Replace the hospital boiler first, before checking the treadmill", "Look for motion or cable routing or grounding or interference from the treadmill drive", "Assume a shop simulator is the possible cause, and skip the treadmill as a source", "Increase the defibrillator default energy as a first step"], f: "Noise that appears only when a treadmill runs often points to motion artifact, cable placement, or electrical interference from the drive. Compare with a standing ECG.", src: "fda-advice" },
    { id: "cb079", ages: 'both', topic: "troubleshooting", s: "An ultrasound unit powers on but shows no image, and a known-good probe on that connector is also dark. The fault is more likely:", c: ["The last probe you used, including when a known-good probe also fails", "In the system (connector or board or software) rather than just one probe", "The hospital boiler in the mechanical plant room", "The pneumatic tourniquet on another patient bed"], f: "If a known-good probe also fails on that port, look at the system side. If only one probe fails on a known-good port, look at that probe. The fault is in the system rather than just one probe.", src: "fda-ultrasound" },
    { id: "cb080", ages: 'both', topic: "troubleshooting", s: "A pulse-oximeter reading is blank on a patient with cold fingers, but a simulator at the same cable reads 98%. This suggests:", c: ["A failed simulator, because the simulator still showed 98%", "A poor peripheral signal, and not a proved monitor failure", "A need to ignore oximetry alarms at the bedside in the unit", "A steam leak from a nearby sterilizer, unrelated to the oximeter"], f: "A good simulator reading with a bad patient waveform points to a poor peripheral signal, not a proved monitor failure. A simulator isolates the device and cable. A good simulator result with a poor patient signal points to perfusion, placement, or ambient light, which clinicians may address. Still treat alarms seriously.", src: "fda-pulseox" },
    { id: "cb081", ages: 'both', topic: "troubleshooting", s: "A ventilator in the shop fails a volume check on a test lung, outside its allowed error. You should:", c: ["Send it to a patient room because the display is pretty", "Keep it out of service and repair or escalate it", "Raise the allowed error yourself on the inspection sticker", "Disable the test-lung alarms and pass the ventilator"], f: "Keep it out of service and repair or escalate it. Life-support equipment that fails a performance test stays out of service until it is corrected and verified. Do not 'pass' it by changing limits without authority.", src: "fda-vent" },
    { id: "cb082", ages: 'both', topic: "troubleshooting", s: "A balloon pump (IABP) in use has a gas-loss alarm. Your first priority is:", c: ["Finish a scheduled scale performance check before you go to the bedside emergency", "Support the clinical team and the patient, then follow the emergency procedure for that device", "Open the drive-gas circuit to confirm a tank size before you arrive at the bedside", "Reset the pump's preventive-maintenance interval in the CMMS before going to the bedside"], f: "An IABP is life-support. A leak or gas-loss alarm is urgent. Help the clinical team with the approved emergency steps and a backup plan; do not treat it as a routine shop call while it is on a patient.", src: "fda-advice" },
    { id: "cb083", ages: 'both', topic: "troubleshooting", s: "An anesthesia machine fails a pre-use leak test. The correct action is:", c: ["Start the case and hope the leak is small enough that it can be ignored", "Do not use it for a case until the leak is found and the check passes", "Bypass the leak check because the last case on that machine was fine", "Cover the leak with tape and proceed to the case, skipping a leak test"], f: "Pre-use checks exist to catch leaks and other faults before a patient is anesthetized. A failed leak test takes the machine out of use until it is repaired and it passes.", src: "fda-advice" },
    { id: "cb084", ages: 'both', topic: "troubleshooting", s: "A surgical table will not unlock to reposition, and the patient is on the table. You should:", c: ["Force the table frame with a large pry bar as a first repair move while the patient is still on it", "Keep the patient safe and use an emergency-unlock method when there is one and do not force unknown parts", "Cut the main structural weld on the table as a first repair move during an active case", "Leave the room and skip telling the clinical team that the table will not unlock with a patient on it"], f: "Keep the patient safe, use an emergency-unlock method if there is one, and do not force unknown parts. With a patient on the table, safety and an approved emergency release come first. Do not improvise with force that could injure the patient or wreck the table.", src: "fda-advice" },
    { id: "cb085", ages: 'both', topic: "troubleshooting", s: "An infant warmer's skin-temperature probe is off the skin, and the unit is in servo mode. The unsafe pattern to watch for is:", c: ["The warmer will cool the room instead in servo mode, leaving heat unchanged", "The heater is liable to overshoot because it does not see a true skin temperature", "The detached probe leaves heater output unchanged in servo mode on the warmer", "The unit will automatically switch to a sterilizer heating cycle in servo mode"], f: "The heater is liable to overshoot because it does not see a true skin temperature. In servo (skin) mode the heater is driven by the probe. A loose or detached probe can lead to overheating. Check probe placement and mode, and follow the device's alarm behavior.", src: "fda-advice" },
    { id: "cb086", ages: 'both', topic: "troubleshooting", s: "A therapeutic ultrasound unit in physical therapy has a worn sound head and a failed completeness-of-output check. You should:", c: ["Turn the output power up to make up for a worn or damaged applicator", "Stop treatments until the applicator and output are corrected", "Let scheduled treatments continue with a handwritten note on the door", "Ignore the failed output test because the treatment timer still works"], f: "If the applicator or output is out of specification, treatments should stop until repair and a passing test. Turning power up is not a safe fix.", src: "fda-ultrasound" },
    { id: "cb087", ages: 'both', topic: "troubleshooting", s: "A video integration system in an OR has no image on the main display, but the endoscope's local screen works. A useful path is:", c: ["Replace the endoscope light source first, though the local screen is good", "Trace the video route: cables and switcher and input selection and that display", "Replace the patient-table motor as the first display fix in that OR", "Increase the ESU power to brighten the display on the main OR screen"], f: "A good local image means the scope is producing video. The fault is likely in routing, selection, cables, or the destination display.", src: "fda-advice" },
    { id: "cb088", ages: 'both', topic: "troubleshooting", s: "A circulating nurse says a new device 'does not work like the old one.' The best first technical step is:", c: ["Tell them the new device is at fault, and skip a check of settings or a known-good unit", "Ask what they expected and confirm settings, and compare to the manual and a known-good unit", "Change clinical set-points, past your authority, to match the old unit", "Walk away and leave the complaint unrecorded"], f: "Many 'it does not work' calls are setup or a difference in workflow. Listen, compare with the manual or a known-good unit, and document. Then repair if there is a real fault.", src: "fda-advice" },
    { id: "cb089", ages: 'both', topic: "troubleshooting", s: "A module in a physiologic monitor loses only the IBP channel, while ECG and NIBP still work. That pattern suggests:", c: ["A total failure of the whole physiologic monitor, on each channel at once", "A fault in that pressure channel or its cable or its transducer interface", "A building-wide power loss affecting the entire clinical floor at once", "A failed hospital boiler in the plant, affecting that one pressure channel"], f: "Start with a fault in that pressure channel, its cable, or its transducer interface. When one parameter fails and others on the same monitor work, start with that channel and its accessories before replacing the entire platform.", src: "fda-advice" },
    { id: "cb090", ages: 'both', topic: "troubleshooting", s: "You finish a repair on a life-support device. Before it returns to service you should:", c: ["Send it back to the floor and skip a function test, to save time", "Test the functions that were affected and complete the required documentation", "Erase the work-order history in the CMMS so the fault stays unseen", "Skip the electrical safety checks that policy still requires for that repair"], f: "Before return to service, test the functions that were affected and complete the required documentation. Return-to-service needs verification of the repair, required safety and performance checks, and a record in the CMMS. Skipping tests or records is not acceptable.", src: "fda-advice" },
    { id: "cb091", ages: 'both', topic: "safety", s: "A protective earth (ground) conductor on a medical device power cord is there mainly to:", c: ["Carry the normal load current in place of the hot conductor, by design of the cord", "Provide a low-impedance fault path so protection is able to operate and touch voltage stays low", "Make insulation unnecessary on each current-carrying conductor in the power cord", "Hold the plug in the wall outlet so it cannot be pulled out during a fault"], f: "A protective earth conductor is there to provide a low-impedance fault path so protection is able to operate and touch voltage stays low. The grounding conductor is a safety path for fault current, not the normal load path. NFPA 99 and IEC 60601 address grounding and leakage in healthcare electrical systems and equipment; consult those standards for limits and methods.", src: "iec-60601", also: ["nfpa-99"], img: "img/cbet-plug.svg", imgAlt: "Front view of a US NEMA 5-15 receptacle with the ground hole down: the wider neutral slot is on the left, the narrower hot slot is on the right, and the ground hole is at the bottom.", imgAsk: true },
    { id: "cb092", ages: 'both', topic: "safety", s: "Macroshock and microshock are different because:", c: ["Macroshock applies to large appliances, and microshock is merely a static-electricity term in the shop", "Microshock concerns small currents that are dangerous when they reach the heart through a conductive path", "Microshock is a radio-frequency interference term used in telemetry and wireless patient monitors", "They are two names for the same floor-outlet wiring and grounding test used in the shop"], f: "Macroshock is a shock through the intact body. Microshock refers to much smaller currents that can be hazardous if a conductive path (for example a catheter or lead) reaches the heart. Design and testing of patient connections take that risk into account. See IEC 60601 and NFPA 99 for the official limits and tests.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb093", ages: 'both', topic: "safety", s: "A GFCI device is intended to:", c: ["Increase leakage current to the patient on purpose as a built-in monitor feature", "Open the circuit when it detects a dangerous imbalance between hot and neutral current", "Replace the equipment grounding conductor in a medical device power cord in full", "Measure ECG amplitude on a diagnostic electrocardiograph recorder at the bedside"], f: "A GFCI is designed to open the circuit when it detects a dangerous imbalance between hot and neutral current. A GFCI compares outgoing and returning current and trips when the difference suggests leakage to ground. It is a personnel-protection device. It does not replace all other grounding and leakage requirements in medical equipment standards.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb094", ages: 'both', topic: "safety", s: "A Safety Data Sheet (SDS) is used to:", c: ["Record a patient's clinical diagnosis in the medical chart", "Identify chemical hazards and how to work with a product safely", "Set a ventilator tidal volume for a newly admitted ICU patient", "Assign an IP address to a bedside physiologic monitor"], f: "An SDS is used to identify chemical hazards and how to work with a product safely. The SDS (formerly MSDS) describes hazards, PPE, storage, and emergency actions for a chemical product. It is not a medical record or a device setting sheet.", src: "osha-elec", also: ["nfpa-99"] },
    { id: "cb095", ages: 'both', topic: "safety", s: "A standard ionizing-radiation trefoil sign is meant to:", c: ["Mark a staff storage closet off the public corridor", "Warn of a radiation hazard in that area or on that source", "Label a fire extinguisher of a different hazard class", "Show the unit's network name"], f: "The trefoil is the standard ionizing-radiation warning symbol. Laser and MRI areas use their own distinctive warnings. Staff should heed posted signs and access rules.", src: "nfpa-99" },
    { id: "cb096", ages: 'both', topic: "safety", s: "Standard precautions in a healthcare facility include:", c: ["Skip hand hygiene whenever gloves are already available in the patient room on that unit", "Hand hygiene and the PPE the task requires while treating body fluids as potentially infectious", "Reuse labeled single-use needles to save money in the clean supply room on that nursing unit", "Eat in a soiled utility room to save time between scheduled patient cases on that nursing unit"], f: "Standard precautions assume that blood and body fluids may be infectious. Hand hygiene, appropriate PPE, safe sharps handling, and cleaning are core practices taught by CDC and required in facilities.", src: "cdc-precautions", also: ["nfpa-99"] },
    { id: "cb097", ages: 'both', topic: "function", s: "CMS (Centers for Medicare and Medicaid Services) is important to hospitals in part because:", c: ["It manufactures infusion pumps and sells them directly to hospital programs", "It sets Conditions of Participation and recognizes accrediting organizations", "It writes Ohm's law as a regulation for hospital electrical safety programs", "It issues state PE licenses for hospital clinical engineers"], f: "CMS oversees federal healthcare payment programs and Conditions of Participation. It also grants deeming authority to certain accrediting bodies. It is not a device maker or a PE board.", src: "cms-cops", also: ["nfpa-99"] },
    { id: "cb098", ages: 'both', topic: "safety", s: "Under IEC 60601-1, which applied-part type has the tightest patient leakage current limits?", c: ["Type B, because it is not isolated from earth", "Type CF (cardiac), compared with type B or BF", "Type B, claiming tighter patient-leakage limits than type CF", "A single chassis limit used for each applied part, omitting a type distinction"], f: "Type CF applied parts, intended for direct cardiac connection, have tighter patient-leakage limits than type B or BF in IEC 60601-1, in both normal and single-fault condition. Typical teaching values are on the order of 10 microamps for CF in normal condition, versus on the order of 100 microamps for B or BF. Confirm the figures in the current edition of the standard and on the device labeling; do not treat unofficial tables as a substitute for the standard.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb099", ages: 'both', topic: "safety", s: "For a given applied-part type, IEC 60601-1 leakage current limits in single-fault condition, compared with normal condition, are:", c: ["Zero, because a single fault means the device has to be shut down", "Higher than in normal condition, but still limited to a stated value", "The same number as in normal condition, for these tests", "Unlimited, as long as a GFCI is installed in the room"], f: "The standard allows a higher leakage current in a specified single-fault condition than in normal condition, but the current is still capped. Type CF remains tighter than type BF in both conditions. NFPA 99 addresses facility electrical safety, including isolated power and testing, separately from the device standard. Use the values and test setup from the edition and labeling that apply.", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb100", ages: 'both', topic: "safety", s: "An MRI warning sign is posted because:", c: ["The room is a quiet reading and waiting area set aside for visitors", "The strong magnetic field pulls ferromagnetic objects and is a serious safety hazard", "The room is equivalent to a public waiting area from a visitor-safety standpoint", "The sign is decorative and is posted for hallway wayfinding"], f: "MRI systems have a powerful magnetic field that can move ferromagnetic objects and also other hazards (for example, implants and time-varying fields). Access and screening rules exist to prevent projectile and implant injuries.", src: "nfpa-99" },
  ]
});
